#!/usr/bin/env bash
# ตัดสินเพดานขนาดของ PR จาก agent — มีข้อยกเว้นเดียวคือ "ย้ายอย่างเดียว" ที่เครื่องพิสูจน์แล้ว
#
# ── ทำไมเพดานถึงมีข้อยกเว้นได้ ──────────────────────────────────────
# เพดาน 150 บรรทัดมีไว้ให้เจ้าของตรวจ PR ของ agent ทันตอนพักเที่ยง
# ตัวเลขบรรทัดเป็นแค่ตัวแทนของคำว่า "ตรวจไหว" และตัวแทนนี้ใช้กับงานย้ายโค้ดไม่ได้:
# ย้ายฟังก์ชันหลายพันบรรทัดโดยไม่แก้สักตัวอักษร ตรวจด้วยตาไม่ไหว
# แต่ **พิสูจน์ด้วยเครื่องได้ทั้งหมด** (.github/scripts/move-proof.mjs)
# ซึ่งแข็งกว่าการเชื่อคำว่า "ย้ายอย่างเดียว" ในหัว PR — ข้อความในหัว PR คือรูรอบที่ 1 ของด่าน vendor
#
# ── ที่มา ────────────────────────────────────────────────────────
# 23 ก.ย. 2026 เจ้าของบอกว่าเขียนโค้ดเองไม่เป็น งานแยกไฟล์ตาม CLAUDE.md §3.1 จึงเป็นงานของ agent ทุกก้อน
# ถ้าไม่มีข้อยกเว้นนี้ แผนแยกไฟล์จะไม่มีวันเกิด หรือไม่ก็ต้องหลบด่านด้วยการตั้งชื่อสาขาให้ไม่ขึ้นต้น claude/
# ซึ่งแย่กว่ามาก เพราะทำให้ด่านทั้งตัวไร้ความหมายโดยไม่มีใครตัดสินใจ
#
# ── ทำไมยังต้องมี label ────────────────────────────────────────────
# เครื่องพิสูจน์ได้ว่า "ไม่มีโค้ดใหม่" แต่การยอมให้ PR ขนาดนี้เข้า main เป็นการตัดสินใจของเจ้าของ
# ใช้กติกาเดียวกับ vendor-gate.sh ทุกข้อ: เขียวเฉพาะรอบที่ "เพิ่งมีคนติด label move-only"
#   push ตามหลัง label → แดงใหม่ · ถอด/ติด label อื่น · ปิดเปิด PR → ไม่นับ
#   (รูรอบ 3–4 ของด่าน vendor — กันไว้แบบเดียวกันตั้งแต่วันแรก)
# และต้องพิสูจน์ผ่าน **ในรอบเดียวกันนั้น** ด้วย — label ไม่ได้แทนการพิสูจน์ ทั้งสองอย่างต้องครบ
#
# ⚠️ ข้อยกเว้นนี้ปลดแค่ "เพดานจำนวนบรรทัด" ข้อเดียว
#    ด่านอื่นทุกข้อ (vendor · .github/ · โหลดจากเน็ต · ลบเทส) ยังตัดสินแยกตามเดิม
#    และ Playwright ยังเป็นตัวยืนยันว่าแอปทำงานเหมือนเดิม — ตัวพิสูจน์ตอบได้แค่ว่าไม่มีโค้ดใหม่
#
# ตัวแปรที่ต้องมี: IS_AGENT APPLINES MOVE_PROVEN PR_EVENT PR_LABEL_NAME
#   MOVE_PROVEN = yes (พิสูจน์ผ่าน) · no (ไม่ผ่าน) · skip (ไม่ได้รันตัวพิสูจน์)
# คืน 0 = ผ่าน · 1 = ตก

set -uo pipefail

SIZE_CAP=150
MOVE_LABEL='move-only'

size_gate() {
  [ "${IS_AGENT:-no}" = yes ] || return 0
  [ "${APPLINES:-0}" -gt "$SIZE_CAP" ] || return 0

  if [ "${MOVE_PROVEN:-skip}" != yes ]; then
    echo "::error::PR จาก agent แก้ไฟล์แอปไป ${APPLINES} บรรทัด (เพดาน ${SIZE_CAP}) — ใหญ่เกินกว่าจะตรวจตอนพักเที่ยง ต้องหยุดถามเจ้าของก่อนแก้ใหญ่ขนาดนี้"
    if [ "${MOVE_PROVEN:-skip}" = no ]; then
      echo "::error::  และพิสูจน์ไม่ได้ว่าเป็นการย้ายอย่างเดียว (ดูรายละเอียดจากตัวพิสูจน์ด้านบน) — ข้อยกเว้นเรื่องย้ายโค้ดจึงใช้ไม่ได้"
    fi
    return 1
  fi

  if [ "${PR_EVENT:-}" = labeled ] && [ "${PR_LABEL_NAME:-}" = "$MOVE_LABEL" ]; then
    echo "::warning::PR นี้ใหญ่ ${APPLINES} บรรทัด แต่พิสูจน์แล้วว่าย้ายอย่างเดียว และเจ้าของเพิ่งติด label ${MOVE_LABEL} ให้รอบนี้"
    echo "::warning::  ตัวพิสูจน์ยืนยันแค่ว่าไม่มีโค้ดใหม่ — ลำดับการโหลดไฟล์ยังต้องพึ่ง Playwright ที่เป็น required check"
    return 0
  fi

  echo "::error::PR นี้ใหญ่ ${APPLINES} บรรทัด (เพดาน ${SIZE_CAP}) · พิสูจน์แล้วว่าย้ายอย่างเดียว — เหลือขั้นเดียวคือให้เจ้าของ 'ติด label ${MOVE_LABEL}' ที่ PR ใบนี้"
  echo "::error::  ถ้าติดไว้อยู่แล้วให้ถอดออกแล้วติดกลับ — เขียวต้องมาจากรอบที่คนเพิ่งตัดสินใจกับ commit ชุดนี้"
  return 1
}

# ให้ source ได้โดยไม่รันทันที (ตัวเทสจะเรียก size_gate เอง)
if [ "${BASH_SOURCE[0]}" = "${0}" ]; then
  size_gate
fi
